local config = {
  ui_story_30360401_1_dialog_content = "Jadi... Ada masalah apa?",
  ui_story_30360401_2_dialog_content = "<color=#e8d9bb>Setelah kegelapan menyelimuti, kupejamkan mataku dan tertidur lelap.</color>",
  ui_story_30360401_3_dialog_content = "Namun, aku terjaga di tengah malam, disambut sepasang mata yang bersinar dalam gelap...",
  ui_story_30360401_4_dialog_content = "Aku yakin apa yang berdiri di hadapanku adalah binatang...",
  ui_story_30360401_5_dialog_content = "Maksudmu, serigala mengawasimu semalam?",
  ui_story_30360401_6_dialog_content = "Ya, aku yakin mungkin itu salah satu dari Shadow Wolf-mu.",
  ui_story_30360401_7_dialog_content = "Tidak mungkin... Aku belum pernah menggunakan Shadow Magic milikku, atau memerintahkan Shadow Wolf milikku untuk melakukannya.",
  ui_story_30360401_8_dialog_content = "Aku tahu... Aku tidak meragukanmu.",
  ui_story_30360401_9_dialog_content = "Namun, ini sudah berjalan selama berhari-hari sampai-sampai aku harus membicarakannya denganmu.",
  ui_story_30360401_10_option_content = "Meski aku tidak punya bukti...",
  ui_story_30360401_11_dialog_content = "Karena aku bisa merasakannya.",
  ui_story_30360401_12_dialog_content = "Maksudmu, melalui kemampuan psikismu?",
  ui_story_30360401_13_dialog_content = "Ya, bisa jadi itu mereka.",
  ui_story_30360401_14_option_content = "Aku yakin itu adalah Shadow Wolf.",
  ui_story_30360401_15_dialog_content = "Mungkinkah mereka bertindak tanpa seizinmu? Mungkinkah mereka bebas berkeliaran saat kamu beristirahat?",
  ui_story_30360401_16_dialog_content = "Entahlah... Mungkin saja?",
  ui_story_30360401_17_dialog_content = "Hei, kenapa kamu pergi ke ruangan PlayerName semalam?",
  ui_story_30360401_18_dialog_content = "<color=#e8d9bb>Shadow Wolf melengkungkan telinga mereka.</color>",
  ui_story_30360401_19_dialog_content = "Sepertinya kamu benar.",
  ui_story_30360401_20_dialog_content = "Dari mana kamu tahu itu?",
  ui_story_30360401_21_dialog_content = "Aku hanya tahu dari reaksi fisik mereka, seperti cara telinga mereka berkedut.",
  ui_story_30360401_22_dialog_content = "Lagi pula, aku tidak sepertimu. Aku tidak bisa bicara dengan hewan.",
  ui_story_30360401_23_dialog_content = "Bukan seperti itu... Lagi pula, memangnya mereka termasuk hewan...?",
  ui_story_30360401_24_dialog_content = "Omong-omong, bisakah kamu awasi Shadow Wolf-mu? Setidaknya cegah mereka datang ke ruanganku dan menatapku saat tengah malam.",
  ui_story_30360401_25_dialog_content = "Baiklah.",
  ui_story_30360401_26_dialog_content = "Kalian dilarang memasuki ruangan PlayerName.",
  ui_story_30360401_27_dialog_content = "<color=#e8d9bb>Shadow Wolf tidak menunjukkan reaksi.</color>",
  ui_story_30360401_28_dialog_content = "Mereka tidak bereaksi.",
  ui_story_30360401_29_option_content = "Tunggu... Kenapa?",
  ui_story_30360401_30_dialog_content = "Dari mana aku tahu? Mungkin mereka punya alasan tersendiri.",
  ui_story_30360401_31_dialog_content = "Itu berarti mereka akan terus datang ke ruanganku untuk menatapku saat tengah malam?",
  ui_story_30360401_32_dialog_content = "Kemungkinan besar.",
  ui_story_30360401_33_dialog_content = "Itu mengganggu... Bagaimana bisa aku tidur jika begitu?",
  ui_story_30360401_32_option_content = "Tidak... Kamu harus meyakinkan mereka!",
  ui_story_30360401_35_dialog_content = "Bagaimana aku bisa membujuk mereka?",
  ui_story_30360401_36_dialog_content = "Kenapa kamu bertanya padaku? Bukankah kamu tuan mereka?",
  ui_story_30360401_37_dialog_content = "Aku belum berhasil mengajari mereka perintah apa pun selain menyerang. Jika mereka sama sekali tidak mendengarkanku, tidak ada yang bisa aku lakukan.",
  ui_story_30360401_38_dialog_content = "Apa yang harus kulakukan?",
  ui_story_30360401_39_dialog_content = "Bisakah kamu terhubung dengan mereka secara psikis? Cobalah berkomunikasi dengan mereka.",
  ui_story_30360401_40_option_content = "Ini sedikit menakutkan.",
  ui_story_30360401_41_dialog_content = "Menakutkan bagaimana?",
  ui_story_30360401_42_dialog_content = "Mereka terlihat seperti binatang misterius, dan tercatat di basis data Colossus sebagai makhluk berbahaya, belum lagi fakta bahwa mereka terlahir dari kemampuanmu.",
  ui_story_30360401_43_dialog_content = "Apakah mereka bisa dianggap sebagai makhluk, aku masih belum tahu. Aku tidak yakin apakah aku bisa berkomunikasi dengan mereka.",
  ui_story_30360401_44_dialog_content = "Aku mendapatkan kemampuan Shadow Wolf dari reruntuhan yang tidak dikenal. Aku bahkan tidak tahu mereka itu apa...",
  ui_story_30360401_45_dialog_content = "Kamu bisa menganggap mereka makhluk ajaib, tetapi bagiku, mereka seperti anjing biasa.",
  ui_story_30360401_46_option_content = "Aku yakin mencobanya tidak akan menjadi masalah...",
  ui_story_30360401_47_dialog_content = "Mereka terlihat seperti anjing manis meski tidak terlihat sama seperti yang tercatat di basis data Soroz.",
  ui_story_30360401_48_dialog_content = "<color=#e8d9bb>Shadow Wolf mulai menunjukkan giginya.</color>",
  ui_story_30360401_49_dialog_content = "Awas! Jaga jarak... Mereka menjadi gelisah.",
  ui_story_30360401_50_dialog_content = "Jangan sentuh mereka terlalu tiba-tiba. Meski mereka disebut Shadow Wolf, kita masih belum tahu dari mana tepatnya makhluk ajaib ini berasal.",
  ui_story_30360401_51_dialog_content = "Jangan melakukan apa pun yang bisa memprovokasi mereka, nanti mereka bisa menyerangmu.",
  ui_story_30360401_52_dialog_content = "Tunggu sebentar. Ini kemampuanmu, tetapi hanya itu yang kamu ketahui soal mereka?",
  ui_story_30360401_53_dialog_content = "Aku mendapat kemampuan ini, tetapi aku belum mempelajarinya secara mendalam. Yang aku tahu aku bisa menggunakannya.",
  ui_story_30360401_54_dialog_content = "Kalau begitu, lebih baik aku menjaga jarak.",
  ui_story_30360401_55_dialog_content = "<color=#e8d9bb>Kamu memejamkan mata lagi dan kembali ke kegelapan, menghalangi gangguan dari luar. Kemudian, kamu mulai berkonsentrasi...</color>",
  ui_story_30360401_56_dialog_content = "Meski aku bisa menggunakan kemampuan psikisku pada mereka, aku masih tidak bisa memulai percakapan sesuai harapan...",
  ui_story_30360401_57_dialog_content = "Tunggu... Tiba-tiba aku merasakan sebuah gambaran!",
  ui_story_30360401_58_dialog_content = "Seekor Shadow Wolf... Tidak, ada lebih dari seekor...",
  ui_story_30360401_59_dialog_content = "Tampak seperti Hydrad di antara mereka!",
  ui_story_30360401_60_dialog_content = "Apa kamu juga pernah ke ruanganku!?",
  ui_story_30360401_61_dialog_content = "...",
  ui_story_30360401_62_dialog_content = "Katakan sesuatu!",
  ui_story_30360401_63_dialog_content = [[
Kamu telah menjawab semua pertanyaanku hingga sekarang.
Kamu tidak merasa bahwa kamulah yang jelas bersalah?]],
  ui_story_30360401_64_dialog_content = "Bantu aku untuk memahami apa yang terjadi di sini.",
  ui_story_30360401_65_dialog_content = "Hmm... Aku memang pergi ke ruanganmu. Lalu kenapa?",
  ui_story_30360401_66_dialog_content = "Kamu adalah dalang di balik semua ini dan sama sekali tidak merasa bersalah!?",
  ui_story_30360401_67_dialog_content = "Kenapa kamu bilang itu tidak mungkin? Kamu mencoba membodohiku dengan menyalahkan Shadow Wolf?",
  ui_story_30360401_68_dialog_content = "Kamu pikir bisa menyembunyikan kebenaran dariku dengan berpura-pura membantu memecahkan masalah?",
  ui_story_30360401_69_dialog_content = "Begitu aku merasakannya, aku sudah tahu!",
  ui_story_30360401_70_dialog_content = "Tidak, sudah kubilang... Semalam itu bukan aku. Aku hanya pernah ke ruanganmu satu kali!",
  ui_story_30360401_71_dialog_content = "Kamu bisa melihatnya juga?",
  ui_story_30360401_72_dialog_content = "Kenapa? Kapan kamu ke sana?",
  ui_story_30360401_73_dialog_content = "Hanya pada hari pertama aku datang ke Colossus. Aku mengamatimu.",
  ui_story_30360401_74_dialog_content = "Alasannya sangat sederhana. Karena aku memutuskan untuk mengikutimu, kurasa setidaknya aku harus mengenali siapa kamu.",
  ui_story_30360401_75_dialog_content = "Tunggu... Firasatku mengatakan alasan mereka bertindak atas kemauan sendiri adalah kamu.",
  ui_story_30360401_76_dialog_content = "Adakah sesuatu yang mengganggumu belakangan ini?",
  ui_story_30360401_77_dialog_content = "Kamu pernah dengar kata-kata: \"Bayangan mengawasimu\"?",
  ui_story_30360401_78_option_content = "Aku pernah.",
  ui_story_30360401_79_dialog_content = "Apakah kata-kata ini telah menyebar di sekitar Umbraton? Aku ingat beberapa orang dari Umbraton pernah membicarakannya.",
  ui_story_30360401_80_dialog_content = "Baiklah, kamu harus lebih memperhatikannya.",
  ui_story_30360401_81_dialog_content = "Maksudku, jika kamu bisa melihat kebenaran melalui kabut.",
  ui_story_30360401_82_option_content = "Aku belum pernah dengar.",
  ui_story_30360401_83_dialog_content = "Kata-kata yang beredar Umbraton lebih dari sekadar rumor. Tanyakan kepada orang lain, maka kamu akan tahu.",
  ui_story_30360401_84_dialog_content = "Jadi, apa hubungannya dengan semua ini?",
  ui_story_30360401_85_dialog_content = "Aku tidak bisa menjelaskannya kepadamu. Kamu cenayang. Kamu perlu melihatnya sendiri.",
  ui_story_30360401_86_dialog_content = "Yang bisa kukatakan adalah bahwa para bayangan memperhatikanmu karena mereka menyukai aromamu.",
  ui_story_30360401_87_dialog_content = "Bukan hanya Shadow Wolf... Nantinya makin banyak lagi.",
  ui_story_30360401_88_dialog_content = "Tunggu, maksudmu... Shadow Wolf masih akan datang ke ruanganku?",
  ui_story_30360401_89_dialog_content = "Juga akan ada lebih banyak makhluk yang datang...",
  ui_story_30360401_90_dialog_content = "Kemungkinan besar.",
  ui_story_30360401_91_dialog_content = "Kamu akan terbiasa selama beberapa hari ke depan. Shadow wolf akan segera pergi begitu mereka bosan memperhatikanmu.",
  ui_story_30360401_92_dialog_content = "Mana bisa. Sudah terlalu banyak yang harus diambil, dan mungkin hanya akan memburuk.",
  ui_story_30360401_93_dialog_content = "Kenapa?",
  ui_story_30360401_94_dialog_content = "Bagaimana... Bagaimana kamu tiba-tiba memutar arah percakapan ini!?",
  ui_story_30360401_95_dialog_content = "Jika hewan-hewan liar itu memaksa mengawasiku saat aku tidur, tentu saja aku akan merasa takut.",
  ui_story_30360401_96_dialog_content = "Kamu menganggap Shadow Wolf sebagai ancaman bagi keselamatanmu?",
  ui_story_30360401_97_dialog_content = "Mungkin saja.",
  ui_story_30360401_98_dialog_content = "Menimbang situasinya, bahkan kamu tidak tahu apa yang bisa mereka lakukan tanpa perintahmu. Bagaimana kamu bisa menjamin mereka tidak akan menyerangku?",
  ui_story_30360401_99_dialog_content = "Ini masalah serius... Itu sebabnya aku datang untuk bertanya apakah kamu bisa membantu.",
  ui_story_30360401_100_dialog_content = "Mereka hanya ingin melihatmu lebih dekat. Anggap saja mereka anjing yang penasaran dan kamu akan baik-baik saja.",
  ui_story_30360401_101_dialog_content = "Namun, karena hal ini mengganggumu, aku tidak bisa mengabaikannya begitu saja. Lagi pula, bisa dianggap ini adalah kesalahanku.",
  ui_story_30360401_102_dialog_content = "Mulai hari ini, aku akan mengawasi mereka saat malam. Jika mereka memaksa pergi ke ruanganmu, akan kucoba untuk menghentikan mereka.",
  ui_story_30360401_103_dialog_content = "Jika aku tak bisa menghentikan mereka, aku akan ikut.",
  ui_story_30360401_104_dialog_content = "Tunggu! Logika macam apa itu?",
  ui_story_30360401_105_dialog_content = "Jika hanya Shadow Wolf yang masuk ke ruanganmu, mungkin kamu merasa terancam. Maka, aku akan pergi dan memastikan mereka tidak akan berbuat apa pun padamu.",
  ui_story_30360401_106_dialog_content = "Takkan kubiarkan sesuatu terjadi padamu.",
  ui_story_30360401_107_dialog_content = "Masalahmu teratasi. Selesai.",
  ui_story_30360201_X1_dialog_content = "Kalian sedang membicarakan apa?",
  ui_story_30360201_1_dialog_content = "Sedang apa kamu di sini? Bukankah kamu pergi ke Lumopolis!?",
  ui_story_30360201_2_dialog_content = "Hmm? Aku...",
  ui_story_30360201_3_dialog_content = "Navigator pemberani, kenapa kamu datang kemari?",
  ui_story_30360201_4_dialog_content = "Jadi, kamu menggunakan kembali muslihat lamamu? Menjauhlah dari PlayerName!",
  ui_story_30360201_5_dialog_content = "Apa? Kamu pikir aku akan melukai PlayerName?",
  ui_story_30360201_6_dialog_content = "Aku hanya ingin bicara dengan PlayerName, di depanmu.",
  ui_story_30360201_7_dialog_content = "Mustahil. Kami tidak akan diam di sini dan mendengarkan kebohonganmu.",
  ui_story_30360201_8_dialog_content = "Hmm? Baiklah, kita dengarkan Tuan Kleken?",
  ui_story_30360201_9_dialog_content = "Kamu akan terseret ke dalam jurang penipuan... Menurutmu, dia hanya bercanda denganmu?",
  ui_story_30360201_10_dialog_content = "Yah, aku suka candaan yang bagus.",
  ui_story_30360201_11_dialog_content = "Namun, bukankah Kleken selaras dengan Shadowlord?",
  ui_story_30360201_12_dialog_content = "Secara teknis, kalian berdua bekerja sama, 'kan?",
  ui_story_30360201_13_dialog_content = "Bukan itu masalahnya.",
  ui_story_30360201_14_dialog_content = "Ingatlah ini, kamu tidak selalu bisa memercayai ucapan orang lain.",
  ui_story_30360201_15_dialog_content = "Jika kamu dibawa pergi diam-diam oleh penipu seperti itu di hadapanku, aku tidak akan melupakannya.",
  ui_story_30360201_16_dialog_content = "Dibawa pergi diam-diam?",
  ui_story_30360201_17_dialog_content = "Mungkin saja. Itu tebakanku.",
  ui_story_30360201_18_dialog_content = "Hmm... Tiba-tiba membuatku kecewa, tepat di depanku? Ini menarik.",
  ui_story_30360201_19_dialog_content = "Kamu masih di sini?",
  ui_story_30360201_20_dialog_content = "Kamu juga ingin aku pergi?",
  ui_story_30360201_21_dialog_content = "Baiklah, sekarang ini bagianku.",
  ui_story_30360201_22_dialog_content = "Baiklah, aku akan pergi.",
  ui_story_30360201_23_dialog_content = "Situasi di antara kalian begitu buruk, ya?",
  ui_story_30360201_24_dialog_content = "Cukup buruk.",
  ui_story_30360201_25_dialog_content = "Aku sedikit ingin tahu apa yang terjadi denganmu.",
  ui_story_30360201_26_dialog_content = "Kepribadian kami kurang cocok saja...",
  ui_story_30360201_27_dialog_content = "<color=#e8d9bb>Kali pertama mereka bertemu di daerah kumuh, kedua anak jalanan kotor ini terdiam dan tidak saling menatap.</color>",
  ui_story_30360201_28_dialog_content = "<color=#e8d9bb>Kali kedua mereka bertemu di tengah kekacauan medan tempur, tatapan mereka tidak bertemu dan keduanya tetap diam.</color>",
  ui_story_30360201_29_dialog_content = "<color=#e8d9bb>Kali ketiga mereka bertemu, yang satu berdiri di sisi kiri Shadowlord, satunya lagi di sebelah kanan Shadowlord.</color>",
  ui_story_30360201_30_dialog_content = "<color=#e8d9bb>Yang satu berjubah panjang, satunya lagi berpakaian mewah, tatapan mereka tidak bertemu dan keduanya tetap diam.</color>",
  ui_story_30360201_31_dialog_content = "<color=#e8d9bb>Kali keempat, kali kelima... tatapan mereka tidak bertemu dan keduanya tetap diam.</color>",
  ui_story_30360201_32_dialog_content = "<color=#e8d9bb>Hingga...</color>",
  ui_story_30360201_33_dialog_content = "Mungkin karena waktu itulah. Biar aku memberitahumu.",
  ui_story_30360201_34_dialog_content = "Jangan mengganggu...",
  ui_story_30360201_35_dialog_content = "Hah? Bukankah kamu akan pergi?",
  ui_story_30360201_36_dialog_content = "Sebenarnya aku hanya bercanda...",
  ui_story_30360201_37_dialog_content = "Biarkan dia pergi. Aku akan memberitahumu.",
  ui_story_30360201_38_option_content = "Oh, Tuan Kleken, bisakah kamu pergi dulu?",
  ui_story_30360201_39_dialog_content = "Kurasa Shadow Wolf telah memamerkan gigi mereka, dan ini membuatku khawatir...",
  ui_story_30360201_40_dialog_content = "Tentu saja, jika kamu memaksa, aku akan pergi.",
  ui_story_30360201_41_dialog_content = "Maafkan ketidaksopananku. Silakan lanjutkan.",
  ui_story_30360201_42_option_content = "Apakah itu perlu?...",
  ui_story_30360201_43_dialog_content = "Tentu saja, itu tidak perlu, pahlawanku yang lembut.",
  ui_story_30360201_44_dialog_content = "<color=#e8d9bb>Shadow Wolf di samping Hydrad mulai menggeram...</color>",
  ui_story_30360201_45_dialog_content = "Anak serigala kecilmu tampak marah...",
  ui_story_30360201_46_dialog_content = "Sebaiknya kamu pergi dari sini sebelum aku marah.",
  ui_story_30360201_47_dialog_content = "Jangan khawatir, aku bisa membaca petunjuk.",
  ui_story_30360201_48_dialog_content = "Situasi yang sudah canggung ini tidak akan kubuat lebih canggung lagi bagi PlayerName. Sampai jumpa di lain kesempatan, pahlawan.",
  ui_story_30360201_49_dialog_content = "Kupikir dia telah benar-benar pergi kali ini.",
  ui_story_30360201_50_dialog_content = "Kamu tampak agak marah hari ini?",
  ui_story_30360201_51_dialog_content = "Kenapa kamu datang tiba-tiba? Bukankah kamu sedang pergi keluar karena ada urusan?",
  ui_story_30360201_52_dialog_content = "Kleken memintaku datang.",
  ui_story_30360201_53_dialog_content = "<size=45>Orang itu lagi!</size>",
  ui_story_30360201_54_dialog_content = "Apa yang dia bilang padamu?",
  ui_story_30360201_55_dialog_content = "Yah, dia hanya memintaku pergi dan melihat-lihat tempat lain pada kesempatan tertentu.",
  ui_story_30360201_56_dialog_content = "Karena kali ini dia menyebutkan Colossus, aku hanya datang untuk memeriksanya.",
  ui_story_30360201_57_dialog_content = "Maaf... Sepertinya alasanmu cukup membingungkan, ya?",
  ui_story_30360201_58_dialog_content = "Tidak... Bukan itu alasannya.",
  ui_story_30360201_59_dialog_content = "Baiklah, kita kembali ke intinya. Jadi, apa yang terjadi di antara kalian berdua?",
  ui_story_30360201_60_dialog_content = "Kurasa kamu sedang mengingat kenangan masa lalumu?",
  ui_story_30360201_61_dialog_content = "Namun, itu tidak penting...",
  ui_story_30360201_62_dialog_content = "<color=#e8d9bb>Hingga percakapan pertama mereka.</color>",
  ui_story_30360201_63_dialog_content = "Mencari Shadowlord? Dia mungkin ada di Lumopolis.",
  ui_story_30360201_64_dialog_content = "Kamu sedang mencari Shadowlord? Dia mungkin ada di Lumopolis.",
  ui_story_30360201_65_dialog_content = "Kali pertama aku berbicara dengannya, dia membohongiku.",
  ui_story_30360201_66_dialog_content = "Itu saja? Itu saja akhir ceritanya?",
  ui_story_30360201_67_dialog_content = "Jika kamu ingin bilang sesuatu, bilang saja. Aku tidak akan keberatan dan aku bisa mendengarnya.",
  ui_story_30360201_68_dialog_content = "Maaf...",
  ui_story_30360201_69_dialog_content = "Ehem... Jadi, maksudmu Kleken berbohong padamu saat kali pertama kamu bicara dengannya?",
  ui_story_30360201_70_dialog_content = "Ya.",
  ui_story_30360201_71_option_content = "Jadi, Shadowlord waktu itu tidak ada di Lumopolis?",
  ui_story_30360201_72_dialog_content = "Aku menunggu di sana seharian, sampai-sampai penjaga datang.",
  ui_story_30360201_73_dialog_content = "Aku memukul mereka sebelum kembali.",
  ui_story_30360201_74_dialog_content = "Kemudian, Shadowlord bilang bahwa dia biasanya tidak pergi ke Lumopolis, jadi itu benar-benar bohong.",
  ui_story_30360201_75_option_content = "Kamu percaya padanya?",
  ui_story_30360201_76_dialog_content = "Aku percaya padanya, aku pergi ke sana, dan aku tidak menemukan apa pun.",
  ui_story_30360201_77_dialog_content = "Begitu, ya...",
  ui_story_30360201_78_dialog_content = "Aku juga memukuli Lumo Guard, menimbulkan beberapa masalah.",
  ui_story_30360201_79_dialog_content = "Tunggu... Kenapa kamu memukuli para penjaga?",
  ui_story_30360201_80_dialog_content = "Karena mereka bersikap sangat kasar padaku.",
  ui_story_30360201_81_dialog_content = "Dia berjongkok di sana bersama anjingnya seharian...",
  ui_story_30360201_82_dialog_content = "Aku anggap dia akan meminta para bangsawan untuk menerimanya masuk, 'kan? Begitu banyak orang yang melakukan itu akhir-akhir ini...",
  ui_story_30360201_83_dialog_content = "Namun, membawa anjing juga? Itu baru kelewatan!",
  ui_story_30360201_84_dialog_content = "Aku hanya ingin mereka diam!",
  ui_story_30360201_85_dialog_content = "Ah, jadi itu salah penjaga.",
  ui_story_30360201_86_dialog_content = "Soal Kleken yang berbohong padamu...",
  ui_story_30360201_87_option_content = "Mungkin kamu juga turut bertanggung jawab...",
  ui_story_30360201_88_dialog_content = "Seperti... karena memercayai kebohongan yang jelas?",
  ui_story_30360201_89_dialog_content = "Andai aku memercayaimu, apakah itu salahku?",
  ui_story_30360201_90_dialog_content = "Bukan itu maksudku!",
  ui_story_30360201_91_dialog_content = "Dialah yang bersalah!",
  ui_story_30360201_92_dialog_content = "Begini, biasanya aku tidak memercayai apa pun yang dia katakan, kecuali rasanya itu benar!",
  ui_story_30360201_93_dialog_content = "Meski itu terdengar agak aneh.",
  ui_story_30360201_94_option_content = "Itu sepenuhnya kesalahan dia!",
  ui_story_30360201_95_dialog_content = "Tuan Kleken memang suka berkata bohong yang tidak artinya.",
  ui_story_30360201_96_dialog_content = "Dia menyebut dirinya sebagai seniman penipu, tetapi juga memperingatkan orang-orang agar tidak memercayainya.",
  ui_story_30360201_97_dialog_content = "Jadi, jangan percaya apa pun perkataannya lagi, dan anggap enteng saja setiap perkataannya.",
  ui_story_30360201_98_dialog_content = "...",
  ui_story_30360201_99_dialog_content = "A-apa itu? Diammu menyakitiku...",
  ui_story_30360201_100_dialog_content = "Maafkan diamku... Hanya saja kamu melebihi harapanku.",
  ui_story_30360201_101_dialog_content = "Awalnya aku ingin memperingatkanmu agar tidak terpengaruh kata-katanya.",
  ui_story_30360201_102_dialog_content = "Sepertinya kamu jauh lebih peka dari yang kubayangkan.",
  ui_story_30360201_103_dialog_content = "Terima kasih atas kepedulianmu, tapi rasanya dia tidak akan berbuat sesuatu yang salah kepadaku.",
  ui_story_30360201_104_dialog_content = "Selain itu, aku tidak tahu apakah mengatakan hal semacam itu akan sedikit mengganggu.",
  ui_story_30360201_105_dialog_content = "Aku tidak ingin ada konflik antara mereka yang datang untuk tinggal di atas Colossus.",
  ui_story_30360201_106_dialog_content = "Jadi...",
  ui_story_30360201_107_dialog_content = "Aku tahu.",
  ui_story_30360201_108_dialog_content = "Kamu benar dan tidak mengganggu. Tidak perlu meragukan dirimu sendiri.",
  ui_story_30360201_109_dialog_content = "Luar biasa. Jadi, karena kita semua bekerja dan hidup bersama di Colossus, kita harus mencoba untuk akur dengan sesama di masa depan!",
  ui_story_30360201_110_dialog_content = "Aku tidak bisa melakukannya.",
  ui_story_30360201_111_dialog_content = "Tunggu... Kupikir kita baru saja sepakat?",
  ui_story_30360201_112_dialog_content = "Aku tidak sepakat dengan apa pun.",
  ui_story_30360201_113_dialog_content = "Kalau dipikir-pikir, sepertinya kamu selalu mengakhiri percakapan dengan ketidakpedulian yang keras semacam ini.",
  ui_story_30360201_114_dialog_content = "Aku hampir terbiasa dengannya.",
  ui_story_30360201_115_dialog_content = "Aku yakin ada hal lain yang perlu kamu urus... Aku tahu itu. Selamat tinggal.",
  ui_story_30360201_116_dialog_content = "Hah!?...",
  ui_story_30360201_117_dialog_content = "Apa? Apakah dia pergi?",
  ui_story_30360201_118_dialog_content = "\"Selamat tinggal\"? Suka atau tidak, aku akan bertemu denganmu atau orang itu lagi.",
  ui_story_30360201_119_dialog_content = "Secara tiba-tiba lagi!",
  ui_story_30360201_120_dialog_content = "Jika suatu hubungan ditujukan untuk berubah, ia akan berubah secara alami. Jika tidak ditujukan untuk itu, seharusnya kamu tidak memaksakannya.",
  ui_story_30360201_121_dialog_content = "Misalnya, keadaan tidak akan pernah menjadi lebih baik antara aku dan hama itu.",
  ui_story_30360201_122_dialog_content = "Sebelum kamu datang, kami mengalami percakapan yang tidak menyenangkan. Yang terjadi adalah...",
  ui_story_30360201_123_dialog_content = "Lagi-lagi kamu, dasar gurita. Kamu melihat...",
  ui_story_30360201_124_dialog_content = "Oh, mungkin kamu bisa menemukan PlayerName di Lumopolis.",
  ui_story_30360201_125_dialog_content = "Apa katamu!?",
  ui_story_30360201_126_dialog_content = "Kalian sedang membicarakan apa?",
  ui_story_30360201_127_dialog_content = "Sedang apa kamu di sini? Bukankah kamu pergi ke Lumopolis!?",
  ui_story_30360201_128_dialog_content = "Si gurita itu masih sama penipunya seperti dulu...",
  ui_story_30360201_129_dialog_content = "Andai kamu tidak muncul tepat waktu, aku akan pergi ke Lumopolis...",
  ui_story_30360601_1_dialog_content = "<color=#e8d9bb>Di bayangan sebuah jalan tanpa nama, terdapat sebuah gudang yang gelap penuh dengan kandang hewan. Dari balik jeruji mereka, berkilauan sepasang mata yang mengancam tanpa henti.</color>",
  ui_story_30360601_2_dialog_content = "<color=#e8d9bb>Dan di kedalaman gudang, dipisahkan oleh tirai yang kusut—</color>",
  ui_story_30360601_3_dialog_content = "<color=#e8d9bb>Plak!</color>",
  ui_story_30360601_4_dialog_content = "...",
  ui_story_30360601_5_dialog_content = "Masih tidak mau bicara, ya? Kamu memang sulit untuk dipecahkan, aku akui itu.",
  ui_story_30360601_6_dialog_content = "Apakah ini cara kamu memperlakukan mereka juga?",
  ui_story_30360601_7_dialog_content = "Bercanda? Itu barang berharga yang kamu bicarakan! Sampah tak berguna seperti kamu bahkan tidak bisa membandingkannya!",
  ui_story_30360601_8_dialog_content = "\"Barang dagangan,\" huh? Aku mengerti... Sepertinya aku harus membawa kamu ke pengadilan setelah semua ini.",
  ui_story_30360601_9_dialog_content = "<color=#e8d9bb>Beberapa waktu sebelumnya</color>",
  ui_story_30360601_10_dialog_content = "Jadi benar itu kamu, Hydrad! Lama tidak berjumpa!",
  ui_story_30360601_11_dialog_content = "PlayerName? Kamu tidak bisa memilih waktu yang lebih buruk untuk muncul.",
  ui_story_30360601_12_dialog_content = "Apakah kamu menggunakan kemampuan psikismu untuk menemukanku? Sudahlah, aku ada urusan penting yang harus diurus sekarang.",
  ui_story_30360601_13_dialog_content = "Apa masalahnya? Wow! Apakah itu...",
  ui_story_30360601_14_dialog_content = "Ya. Seperti yang bisa kamu lihat, itu adalah <color=#FFB400>wolf liar</color>.",
  ui_story_30360601_15_dialog_content = "Seekor serigala liar? Aku belum pernah melihatnya sebelumnya... Tampaknya agak mirip dengan Shadow Wolf-mu, bukan?",
  ui_story_30360601_16_dialog_content = "Dari mana tepatnya asalmu?",
  ui_story_30360601_17_dialog_content = "Aku? Yah, saya—",
  ui_story_30360601_18_dialog_content = "Maksudku serigala.",
  ui_story_30360601_19_dialog_content = "... Tunggu, apakah kamu benar-benar sedang berkomunikasi dengan serigala sekarang?",
  ui_story_30360601_20_dialog_content = "Tentu saja tidak. Tidak seperti kamu, aku tidak bisa berbicara dengan hewan.",
  ui_story_30360601_21_dialog_content = "<color=#e8d9bb>Serigala itu mengeluarkan suara menggeram yang putus asa. Meskipun matanya berkilauan dengan ganas, otot-ototnya terlalu lemah untuk menopang tubuhnya yang lemah—</color>",
  ui_story_30360601_22_dialog_content = "Orang-orang ini sangat peka. Mereka bisa memahami perasaan orang lain, sama seperti aku bisa memahami apa yang mereka pikirkan.",
  ui_story_30360601_23_dialog_content = "Serigala adalah hewan yang hidup berkelompok, tetapi yang satu ini sendirian, terluka, dan sangat waspada terhadapku.",
  ui_story_30360601_24_dialog_content = "Serigala penyendiri tidak muncul begitu saja di Umbraton. Pasti ada yang membawanya ke sini. Keluarlah, Shadow Wolf.",
  ui_story_30360601_25_dialog_content = "Lihat? Kamu berada di tempat yang baik, sekarang berhenti berhati-hati terhadapku.",
  ui_story_30360601_26_dialog_content = "Saya perlu kamu untuk mengajukan pertanyaan, PlayerName.",
  ui_story_30360601_27_option_content = "Apa? Aku?",
  ui_story_30360601_28_dialog_content = "Ya, kamu. Cukup tanyakan apa yang terjadi padanya.",
  ui_story_30360601_29_option_content = "Akan kucoba, tentu saja...",
  ui_story_30360601_30_dialog_content = "Mendekatlah. Tak ada yang perlu ditakutkan.",
  ui_story_30360601_31_dialog_content = "Orang ini mungkin memiliki teman di sekitar sini, jadi pastikan untuk memperhatikan apa yang dikatakannya.",
  ui_story_30360601_32_dialog_content = "<color=#e8d9bb>Gudang yang kotor dan rusak berkelebat di pikiran serigala, begitu juga dengan serigala-serigala lainnya yang terkunci dalam kandang.</color>",
  ui_story_30360601_33_dialog_content = "<color=#e8d9bb>Selain dari ini, sejumlah adegan yang lebih brutal muncul—</color>",
  ui_story_30360601_34_dialog_content = "H-Hydrad...",
  ui_story_30360601_35_dialog_content = "Ada apa? Kau baik-baik saja?",
  ui_story_30360601_36_dialog_content = "Hei! Sadarkan dirimu, PlayerName!",
  ui_story_30360601_37_dialog_content = "A-Aku baik-baik saja, aku baru saja melihat banyak kenangan buruk sekaligus... Maaf jika aku membuatmu khawatir.",
  ui_story_30360601_38_dialog_content = "Tidak, ini salahku. Seharusnya aku tidak memintamu terlibat saat kamu hanya lewat saja.",
  ui_story_30360601_39_dialog_content = "Tak apa, sungguh! Ini bukan pertama kalinya hal ini terjadi padaku...",
  ui_story_30360601_40_dialog_content = "Bagaimanapun, ada hal-hal yang lebih penting untuk dikhawatirkan! Serigala ini membutuhkan bantuan kita, Hydrad!",
  ui_story_30360601_41_dialog_content = "Kamu benar. Serigala ini dan kawannya ditangkap dan dibawa kesini tanpa keinginan mereka, tapi yang ini berhasil melarikan diri.",
  ui_story_30360601_42_dialog_content = "Mereka disimpan di sebuah gudang kotor di suatu tempat. Juga...",
  ui_story_30360601_43_dialog_content = "Orang-orang yang menahan mereka di sana sangat mengerikan. Mereka sama sekali tidak peduli tentang kehidupan serigala-serigala ini.",
  ui_story_30360601_44_dialog_content = "... Saya memiliki ide yang cukup baik tentang jenis orang yang ada di balik ini. Geng seperti milik mereka telah diluruskan di masa lalu, tetapi beberapa dari mereka mencoba untuk mengembalikan hari-hari lama.",
  ui_story_30360601_45_dialog_content = "Dan sayangnya, selalu saja ada orang kaya dengan selera yang buruk yang mendanai operasi mereka.",
  ui_story_30360601_46_dialog_content = "Aku tidak akan membiarkan mereka lolos begitu saja.",
  ui_story_30360601_47_dialog_content = "Apa yang kamu rencanakan untuk lakukan, Hydrad?",
  ui_story_30360601_48_dialog_content = "Kamu bilang kamu baru saja melihat sekelompok kenangan buruk, kan? Itu memberitahuku bahwa tidak ada waktu untuk disia-siakan jika saya ingin menyelamatkan nyawa mereka.",
  ui_story_30360601_49_dialog_content = "Baiklah serigala, dengarkan. Jika kamu ingin menyelamatkan teman-temanmu, maka kamu harus bekerja sama denganku.",
  ui_story_30360601_50_dialog_content = "Beritahu itu untuk mengikutiku agar aku bisa membantunya.",
  ui_story_30360601_51_dialog_content = "Serahkan saja padaku.",
  ui_story_30360601_52_dialog_content = "Sekarang aku hanya perlu ganti baju. Beri aku waktu sebentar.",
  ui_story_30360601_53_dialog_content = "Hydrad? Dia pergi begitu cepat... Apakah dia sudah memiliki rencana?",
  ui_story_30360601_54_dialog_content = "<color=#e8d9bb>Tak lama setelahnya—</color>",
  ui_story_30360601_55_dialog_content = "Aku kembali, sekarang bagaimana menurutmu?",
  ui_story_30360601_56_dialog_content = "Sekarang aku terlihat seperti orang kaya yang tidak punya otak, benar?",
  ui_story_30360601_57_dialog_content = "Hydrad, kamu...",
  ui_story_30360601_58_dialog_content = "Kamu terlihat sangat keren sekarang! Eh—maksudku lebih keren dari sebelumnya! Pokoknya, ini benar-benar berbeda dari gayamu yang biasa.",
  ui_story_30360601_59_dialog_content = "(Saya tidak yakin dia benar-benar cocok dengan julukan \"orang kaya tanpa otak,\" tapi ini harus cukup sebagai penyamaran.)",
  ui_story_30360601_60_dialog_content = "Dengan beberapa sentuhan akhir, saya akan membuatnya terlihat seperti saya adalah pemilik serigala ini...",
  ui_story_30360601_61_dialog_content = "Di sana. Begitu mereka melihatku berjalan-jalan di jalanan dengan itu, saya yakin hyena-hyena itu akan merangkak keluar.",
  ui_story_30360601_62_dialog_content = "Sementara saya melakukan itu, saya perlu kamu untuk merasakan lokasi kawanan serigala ini, PlayerName.",
  ui_story_30360601_63_dialog_content = "Saya tidak ingin membahayakanmu, tapi merasakan area sekitar tidak menjadi masalah, bukan?",
  ui_story_30360601_64_dialog_content = "Jika kamu melihat aku pergi ke suatu tempat dengan orang lain, segera beri tahu Shadowlord.",
  ui_story_30360601_65_dialog_content = "Orang-orang ini berpikir mereka bisa bersembunyi dari bayangan, tetapi dengan bantuanmu, kita pasti akan mencari dan menemukan mereka.",
  ui_story_30360601_66_dialog_content = "Aku berjanji akan berusaha sebaik mungkin, Hydrad.",
  ui_story_30360601_67_dialog_content = "Tunggu, apa yang kamu—hai!",
  ui_story_30360601_68_dialog_content = "Di sana. Kamu sudah tampak seperti bukan ancaman, jadi cukup sembunyikan wajahmu dengan topimu, dan tidak ada yang akan memperhatikanmu.",
  ui_story_30360601_69_dialog_content = "Aku pergi sekarang. Sisanya aku serahkan padamu.",
  ui_story_30360601_70_dialog_content = "O-Oke! Jangan kecewakan Hydrad, jangan kecewakan Hydrad, jangan kecewakan—",
  ui_story_30360601_71_dialog_content = "Apa yang kau gumamkan di sana?",
  ui_story_30360601_72_dialog_content = "Sudahlah, sudah waktunya untuk pergi.",
  ui_story_30360601_73_dialog_content = "Kau 'kan telah melalui masa yang sangat sulit, bukan?",
  ui_story_30360601_74_dialog_content = "Auuu—",
  ui_story_30360601_75_dialog_content = "Bersabarlah sedikit lebih lama. Kau akan mendapatkan pembalasanmu cukup segera.",
  ui_story_30360601_76_dialog_content = "<color=#e8d9bb>Beberapa waktu kemudian—</color>",
  ui_story_30360601_77_dialog_content = "Serigala hidup, ya? Itu hewan peliharaan yang cukup unik yang kamu miliki di sana, teman.",
  ui_story_30360601_78_dialog_content = "Ya? Apa hubungannya denganmu?",
  ui_story_30360601_79_dialog_content = "Tidak perlu kasar, teman! Aku bisa melihat bahwa kamu punya selera yang bagus, jadi bolehkah aku menawarkan beberapa barang baru kami?",
  ui_story_30360601_80_dialog_content = "Ada yang berwarna solid? Mantel mereka juga harus mengkilap.",
  ui_story_30360601_81_dialog_content = "Aku benar—kamu memang tahu banyak hal! Kami punya semua itu dan lebih banyak lagi, kawan!",
  ui_story_30360601_82_dialog_content = "Spesimen terbaik kami memiliki bulu yang berkilau seperti minyak, dan mereka sangat ganas!",
  ui_story_30360601_83_dialog_content = "Begitu kamu melihat mereka, kamu akan tahu mereka adalah serigala tempur yang sempurna. Mereka hanya terlihat seperti itu karena betapa kuatnya mereka!",
  ui_story_30360601_84_dialog_content = "Apakah orang-orangmu tidak khawatir tentang Shadowlord?",
  ui_story_30360601_85_dialog_content = "Para bajingan di Lumopolis terlalu pengecut untuk turun ke sini hanya untuk membeli hewan liar, jadi siapa sebenarnya pelangganmu?",
  ui_story_30360601_86_dialog_content = "Hahaha, kamu menanyakan banyak sekali pertanyaan, teman!",
  ui_story_30360601_87_dialog_content = "Satu-satunya cara untuk menyelundupkan serigala-serigala ini ke kota ini tanpa memperingatkan Guild Umbraton adalah dengan membius mereka sepanjang perjalanan.",
  ui_story_30360601_88_dialog_content = "Heh, itu berarti mereka belum makan selama berhari-hari, kan? Itu tidak akan membuat bulu mereka tetap berkilau.",
  ui_story_30360601_89_dialog_content = "Hei teman... Siapa kamu sebenarnya?",
  ui_story_30360601_90_dialog_content = "Hanya seseorang yang bekerja di bidang yang serupa dan tertarik dengan operasi kecilmu, itu saja.",
  ui_story_30360601_91_dialog_content = "Jadi, kamu tidak berencana untuk membeli serigala dari kami?",
  ui_story_30360601_92_dialog_content = "Tidak, terima kasih. Saya sudah punya banyak.",
  ui_story_30360601_93_dialog_content = "Tsk, mencoba ikut campur dalam bisnis kami, ya? Kamu pikir kamu sedang berbicara dengan siapa, punk?",
  ui_story_30360601_94_dialog_content = "Lebih baik berbagi kekayaan, bukan menurutmu?",
  ui_story_30360601_95_dialog_content = "Dengar itu, anak-anak? Sepertinya kita punya komedian sejati di sini!",
  ui_story_30360601_96_dialog_content = "Kamu memilih orang yang salah untuk diganggu hari ini, Nak. Sekarang beri tahu aku, kamu bekerja untuk siapa!",
  ui_story_30360601_97_dialog_content = "Sudah cukup sulit berbisnis di Umbraton. Dengan orang-orang seperti kamu, bagaimana kita bisa bertahan di sini?",
  ui_story_30360601_98_dialog_content = "Haruskah saya peduli?",
  ui_story_30360601_99_dialog_content = "Kepung dia! Jika kamu tidak ingin terluka, lebih baik ikut dengan tenang.",
  ui_story_30360601_100_dialog_content = "Kamu tidak mau mati, 'kan?",
  ui_story_30360601_101_dialog_content = "... Baiklah kalau begitu.",
  ui_story_30360601_102_dialog_content = "<color=#e8d9bb>Para penyelundup memenjarakan Hydrad di gudang mereka, di mana dia tetap berada dalam waktu yang sangat lama.</color>",
  ui_story_30360601_103_dialog_content = "Kamu lebih tangguh dari yang terlihat, Nak. Bahkan setelah dipukuli seperti ini, kamu masih tidak mau menyerah pada teman-temanmu?",
  ui_story_30360601_104_dialog_content = "Siapa kau pikir kau, berani mengajak kami berkelahi di wilayah kami...",
  ui_story_30360601_105_dialog_content = "Bos, lihat apa yang kami temukan ketika kami melepas kalung serigalanya! Ini sama dengan yang melarikan diri sebelumnya!",
  ui_story_30360601_106_dialog_content = "Sial, aku tahu menemukan pria ini di jalan terlalu bagus untuk menjadi kenyataan!",
  ui_story_30360601_107_dialog_content = "Apakah ini semua dari kalian? Tidak banyak serigala di sini juga... Apakah ini benar-benar semua \"barang dagangan\" kalian juga?",
  ui_story_30360601_108_dialog_content = "Jika begitu, saya sarankan Anda menyerah sebelum teman saya memutuskan untuk muncul.",
  ui_story_30360601_109_dialog_content = "Kamu punya keinginan mati, teman? Kamu harus tahu, <color=#FFB400>Spearows</color> membiarkan kami menjalankan operasi kami di wilayah mereka, dan—",
  ui_story_30360601_110_dialog_content = "Diam, kau idiot! Kita seharusnya sedang menginterogasinya!",
  ui_story_30360601_111_dialog_content = "Sial, sepertinya kita harus berhenti main-main.",
  ui_story_30360601_112_dialog_content = "Simpan itu. Saya sama sekali tidak seperti kalian, orang-orang bodoh.",
  ui_story_30360601_113_dialog_content = "Itu karena saya percaya pada pria itu... teman saya, maksudnya.",
  ui_story_30360601_114_dialog_content = "Ada apa?",
  ui_story_30360601_115_dialog_content = "Kita dalam masalah, bos! Shadowlord ada di sini, dan orang-orangnya juga...",
  ui_story_30360601_116_dialog_content = "A-Apa?",
  ui_story_30360601_117_dialog_content = "Heh, mereka butuh waktu yang cukup lama.",
  ui_story_30360601_118_dialog_content = "Lupakan orang ini, bos! Kita masih bisa kabur lewat pintu belakang!",
  ui_story_30360601_119_dialog_content = "Tidak mungkin.",
  ui_story_30360601_120_dialog_content = "Aku muak menunggu—keluarlah, Shadow Wolf!",
  ui_story_30360601_121_dialog_content = "Dari mana benda-benda ini berasal?",
  ui_story_30360601_122_dialog_content = "Hati-hati, bos! Anak itu berhasil membebaskan diri!",
  ui_story_30360601_123_dialog_content = "Sekarang saatnya untuk pelajaran tentang rasa sakit—dan <color=#FFB400>serigala</color> akan mengajarkannya kepada kamu!",
  ui_story_30360601_124_dialog_content = "M-Mundur!",
  ui_story_30360601_125_dialog_content = "Bos!",
  ui_story_30360601_126_dialog_content = "Lebih baik aku mengakhiri ini sebelum PlayerName tiba. Aku tidak ingin dia melihat apa yang akan terjadi.",
  ui_story_30360601_127_dialog_content = "<color=#e8d9bb>Beberapa waktu kemudian.</color>",
  ui_story_30360601_128_dialog_content = "Terima kasih sekali lagi atas bantuanmu.",
  ui_story_30360601_129_option_content = "Jangan sebutkan itu. Saya bahkan belum masuk sebelum mereka memberi tahu saya bahwa itu sudah selesai.",
  ui_story_30360601_130_dialog_content = "Sungguh? Bagus.",
  ui_story_30360601_131_option_content = "Entahlah, rasanya aku tidak melakukan banyak hal.",
  ui_story_30360601_132_dialog_content = "Tanpa kamu, rencana ini tidak akan pernah berhasil.",
  ui_story_30360601_133_dialog_content = "Mereka memiliki jumlah yang banyak, serta rute pelarian.",
  ui_story_30360601_134_dialog_content = "Karena kamu membawa Shadowlord ke sini, kami bisa menjebak mereka semua di satu tempat.",
  ui_story_30360601_135_dialog_content = "Oh, heheh... Saya cukup yakin kamu hanya sedang memuji saya, tapi saya senang bisa membantu!",
  ui_story_30360601_136_dialog_content = "Tidak, kamu pasti layak mendapatkan kepercayaanku. Bahkan, kehadiran bayanganmu sekarang lebih cocok dengan diriku.",
  ui_story_30360601_137_dialog_content = "Ngomong-ngomong, serigala itu dari sebelumnya telah bersatu kembali dengan kelompoknya, dan mereka akan segera dikirim kembali ke rumah mereka.",
  ui_story_30360601_138_dialog_content = "Lagi pula, selalu lebih baik bagi hewan kawanan untuk tetap bersama-sama.",
  ui_story_30360601_139_dialog_content = "Itu berlaku untukmu juga, Hydrad. Kamu dan Shadowlord membentuk tim yang luar biasa!",
  ui_story_30360601_140_dialog_content = "... Anyway, aku penasaran apa yang akan terjadi pada Spearows lainnya yang terlibat dalam jaringan penyelundupan ini.",
  ui_story_30360601_141_dialog_content = "Si gurita yang busuk itu bertanggung jawab untuk menangani mereka, jadi siapa tahu kapan semuanya akan selesai?",
  ui_story_30360601_142_dialog_content = "Tapi itu tidak penting sekarang. Ayo, kita pergi.",
  ui_story_30360601_143_dialog_content = "Hah? Kemana kita pergi?",
  ui_story_30360601_144_dialog_content = "Kamu sedang melakukan sesuatu sebelum kita bertemu, bukan? Aku terlalu sibuk dengan urusan serigala ini sampai-sampai tidak mendengar apa yang kamu katakan.",
  ui_story_30360601_145_dialog_content = "Kamu telah membantuku, jadi sekarang giliran saya untuk membantu kamu.",
  ui_story_30360601_146_dialog_content = "Ayo kita pergi. Apapun yang perlu kamu lakukan, aku akan ada di sana untuk membantu.",
  ui_story_30360601_147_dialog_content = "Jadi apa rencananya?"
}
